func liteClean(path string) string {
	originalPath := path
	volLen := volumeNameLen(path)
	path = path[volLen:]
	if path == "" {
		if volLen > 1 && liteIsPathSeparator(originalPath[0]) && liteIsPathSeparator(originalPath[1]) {
			// should be UNC
			return liteFromSlash(originalPath)
